-- QUERY 1
select * from (
select 1 n, 'B1 quotation_items decision columns, NOT NULL default pending (expect 2, true)' check_name,
  (select count(*) from information_schema.columns where table_schema='public' and table_name='quotation_items' and column_name in ('client_decision','client_decided_at'))::text
  ||', '||coalesce((select (is_nullable='NO' and column_default like '''pending''%')::text from information_schema.columns where table_schema='public' and table_name='quotation_items' and column_name='client_decision'), 'MISSING') result
union all select 2, 'B2 sample functions: return type (expect move_sample=uuid, receive_sample=uuid)', coalesce((select string_agg(proname||'='||prorettype::regtype::text, ', ' order by proname) from pg_proc where pronamespace='public'::regnamespace and proname in ('move_sample','receive_sample')), 'MISSING')
union all select 3, 'B3 sample functions: SECURITY DEFINER + fixed search_path + row lock + anon cannot run + signed-in can (expect 2,2,1,0,2)', (select count(*) from pg_proc where pronamespace='public'::regnamespace and proname in ('move_sample','receive_sample') and prosecdef and array_to_string(proconfig, ',') like '%search_path=public%')::text||','||(select count(*) from pg_proc where pronamespace='public'::regnamespace and proname in ('move_sample','receive_sample') and prosrc like '%has_any_role%')::text||','||(select count(*) from pg_proc where pronamespace='public'::regnamespace and proname='move_sample' and prosrc like '%for update%')::text||','||(select count(*) from pg_proc p where pronamespace='public'::regnamespace and proname in ('move_sample','receive_sample') and has_function_privilege('anon', p.oid, 'execute'))::text||','||(select count(*) from pg_proc p where pronamespace='public'::regnamespace and proname in ('move_sample','receive_sample') and has_function_privilege('authenticated', p.oid, 'execute'))::text
union all select 4, 'B4 holder checks allow team (expect 2)', (select count(*) from pg_constraint where conname in ('sample_movements_from_holder_check','sample_movements_to_holder_check') and pg_get_constraintdef(oid) like '%team%')::text
union all select 5, 'B5 order_status_history new columns (expect 3)', (select count(*) from information_schema.columns where table_schema='public' and table_name='order_status_history' and column_name in ('assigned_to','department_id','stage_due_at'))::text
union all select 6, 'B6 cost columns still readable by anon/authenticated (expect 0)', (select count(*) from information_schema.column_privileges where table_schema='public' and grantee in ('anon','authenticated') and privilege_type='SELECT' and ((table_name='orders' and column_name in ('product_cost','printing_cost','courier_cost','other_cost','total_cost','gross_profit')) or (table_name='order_items' and column_name='supplier_cost_snapshot') or (table_name='products' and column_name in ('supplier_cost','internal_margin','internal_notes')) or (table_name='product_suppliers' and column_name='supplier_cost')))::text
union all select 7, 'B7 non-cost columns still readable: orders.order_value for authenticated, products.price for anon (expect 1,1)', (select count(*) from information_schema.column_privileges where table_schema='public' and table_name='orders' and grantee='authenticated' and privilege_type='SELECT' and column_name='order_value')::text||','||(select count(*) from information_schema.column_privileges where table_schema='public' and table_name='products' and grantee='anon' and privilege_type='SELECT' and column_name='price')::text
union all select 8, 'B8 cost reader functions: SECURITY DEFINER + fixed search_path (expect 4)', (select count(*) from pg_proc where pronamespace='public'::regnamespace and proname in ('order_cost_summary','order_item_supplier_costs','product_cost_summary','product_supplier_costs') and prosecdef and array_to_string(proconfig, ',') like '%search_path=public%')::text
union all select 9, 'B9 cost reader functions: anon can run, signed-in can run (expect 0,4)', (select count(*) from pg_proc p where pronamespace='public'::regnamespace and proname in ('order_cost_summary','order_item_supplier_costs','product_cost_summary','product_supplier_costs') and has_function_privilege('anon', p.oid, 'execute'))::text||','||(select count(*) from pg_proc p where pronamespace='public'::regnamespace and proname in ('order_cost_summary','order_item_supplier_costs','product_cost_summary','product_supplier_costs') and has_function_privilege('authenticated', p.oid, 'execute'))::text
union all select 10, 'B10 cost readers gate on role admin/accounts/management and on suppliers.cost_view (expect true,true,true,true)', coalesce((select (prosrc like '%''admin'', ''accounts'', ''management''%')::text from pg_proc where pronamespace='public'::regnamespace and proname='order_cost_summary'), 'MISSING')||','||coalesce((select (prosrc like '%''admin'', ''accounts'', ''management''%')::text from pg_proc where pronamespace='public'::regnamespace and proname='product_cost_summary'), 'MISSING')||','||coalesce((select (prosrc like '%suppliers.cost_view%')::text from pg_proc where pronamespace='public'::regnamespace and proname='order_item_supplier_costs'), 'MISSING')||','||coalesce((select (prosrc like '%suppliers.cost_view%')::text from pg_proc where pronamespace='public'::regnamespace and proname='product_supplier_costs'), 'MISSING')
union all select 11, 'B11 rate_limit_events: RLS on, no policies, no API privileges (expect true, 0, 0)', coalesce((select relrowsecurity::text from pg_class where oid = to_regclass('public.rate_limit_events')), 'MISSING')||', '||(select count(*) from pg_policies where schemaname='public' and tablename='rate_limit_events')::text||', '||(select count(*) from information_schema.table_privileges where table_schema='public' and table_name='rate_limit_events' and grantee in ('anon','authenticated'))::text
union all select 12, 'B12 rate_limit_check: anon, signed-in, service_role may run (expect false,false,true)', coalesce(has_function_privilege('anon', to_regprocedure('public.rate_limit_check(text,text,integer,integer)')::oid, 'execute')::text||','||has_function_privilege('authenticated', to_regprocedure('public.rate_limit_check(text,text,integer,integer)')::oid, 'execute')::text||','||has_function_privilege('service_role', to_regprocedure('public.rate_limit_check(text,text,integer,integer)')::oid, 'execute')::text, 'MISSING')
union all select 13, 'B13 order cost rule = option B in the converter: no invented cost, positive supplier cost only, profit stored as 0 (expect true,true,true)', coalesce((select (prosrc like '%v_unknown_cost_lines%' and prosrc not like '%0.62%')::text from pg_proc where pronamespace='public'::regnamespace and proname='convert_quotation_to_order'), 'MISSING')||','||coalesce((select (prosrc like '%supplier_cost > 0%')::text from pg_proc where pronamespace='public'::regnamespace and proname='convert_quotation_to_order'), 'MISSING')||','||coalesce((select (prosrc like '%v_cost, v_cost, 0, q.campaign_id%')::text from pg_proc where pronamespace='public'::regnamespace and proname='convert_quotation_to_order'), 'MISSING')
union all select 14, 'B14 item-level quotation response: SECURITY DEFINER, fixed search_path, anon cannot run (expect true,false)', coalesce((select (prosecdef and array_to_string(proconfig, ',') like '%search_path=public%')::text from pg_proc where pronamespace='public'::regnamespace and proname='client_respond_quotation_items'), 'MISSING')||','||coalesce(has_function_privilege('anon', to_regprocedure('public.client_respond_quotation_items(uuid,jsonb,text)')::oid, 'execute')::text, 'MISSING')
union all select 15, 'B15 both respond functions refuse an expired quotation (expect 2)', (select count(*) from pg_proc where pronamespace='public'::regnamespace and proname in ('client_respond_quotation','client_respond_quotation_items') and prosrc like '%has expired%')::text
union all select 16, 'C1 guard triggers exist and run BEFORE (expect payments_no_overpay BEFORE INSERT OR UPDATE, requirements_workflow_guard BEFORE UPDATE)', coalesce((select string_agg(tgname||' '||case when pg_get_triggerdef(oid) like '%BEFORE INSERT OR UPDATE%' then 'BEFORE INSERT OR UPDATE' when pg_get_triggerdef(oid) like '%BEFORE UPDATE%' then 'BEFORE UPDATE' else 'OTHER' end, ', ' order by tgname) from pg_trigger where not tgisinternal and tgname in ('requirements_workflow_guard','payments_no_overpay')), 'none')
union all select 17, 'C2 workflow guard refuses direct stage changes by API roles and freezes budget/quantity (expect true,true)', coalesce((select (prosrc like '%authenticated%' and prosrc like '%workflow_stage%')::text from pg_proc where pronamespace='public'::regnamespace and proname='requirement_workflow_guard'), 'MISSING')||','||coalesce((select (prosrc like '%new.budget is distinct from old.budget%')::text from pg_proc where pronamespace='public'::regnamespace and proname='requirement_workflow_guard'), 'MISSING')
union all select 18, 'C3 overpayment trigger locks the invoice and compares totals (expect true,true)', coalesce((select (prosrc like '%for update%')::text from pg_proc where pronamespace='public'::regnamespace and proname='payments_no_overpay'), 'MISSING')||','||coalesce((select (prosrc like '%would exceed the invoice amount%')::text from pg_proc where pronamespace='public'::regnamespace and proname='payments_no_overpay'), 'MISSING')
union all select 19, 'C4 accepted-lines functions are SECURITY INVOKER (expect quotation_accepted_items=false, quotation_accepted_total=false)', coalesce((select string_agg(proname||'='||prosecdef::text, ', ' order by proname) from pg_proc where pronamespace='public'::regnamespace and proname in ('quotation_accepted_items','quotation_accepted_total')), 'MISSING')
union all select 20, 'C5 audit_select hides a user''s own cost-bearing rows; only internal users insert (expect true,true,true)', coalesce((select (qual like '%can_management_read()%' and qual like '%product_suppliers%' and qual like '%order_items%')::text from pg_policies where schemaname='public' and tablename='audit_logs' and policyname='audit_select'), 'MISSING')||','||coalesce((select (with_check like '%is_internal()%' and with_check like '%auth.uid()%')::text from pg_policies where schemaname='public' and tablename='audit_logs' and policyname='audit_insert'), 'MISSING')||','||(select (count(*) = 2)::text from pg_policies where schemaname='public' and tablename='audit_logs')
union all select 21, 'C6 audit trigger now redacts: write_audit calls audit_redact (expect true)', coalesce((select (prosrc like '%audit_redact%')::text from pg_proc where pronamespace='public'::regnamespace and proname='write_audit'), 'MISSING')
union all select 22, 'C7 notifications: insert needs internal user, update needs a real check, only read_at updatable (expect true,true,read_at)', coalesce((select (with_check like '%is_internal()%' and with_check not like '%is_client()%')::text from pg_policies where schemaname='public' and tablename='notifications' and policyname='notifications_insert_internal'), 'MISSING')||','||coalesce((select (with_check is not null and with_check <> 'true')::text from pg_policies where schemaname='public' and tablename='notifications' and policyname='notifications_update'), 'MISSING')||','||coalesce((select string_agg(column_name, ',') from information_schema.column_privileges where table_schema='public' and table_name='notifications' and grantee='authenticated' and privilege_type='UPDATE'), 'none')
union all select 23, 'C8 tasks status check allows blocked (expect true)', coalesce((select (pg_get_constraintdef(oid) like '%blocked%')::text from pg_constraint where conname='tasks_status_check'), 'MISSING')
union all select 24, 'C9 sign-up: role/company only from app_metadata, default client_user (expect true,true,true)', coalesce((select (prosrc like '%raw_app_meta_data%')::text from pg_proc where pronamespace='public'::regnamespace and proname='handle_new_user'), 'MISSING')||','||coalesce((select (prosrc not like '%raw_user_meta_data->>''role''%' and prosrc not like '%raw_user_meta_data->>''company_id''%')::text from pg_proc where pronamespace='public'::regnamespace and proname='handle_new_user'), 'MISSING')||','||coalesce((select (prosrc like '%client_user%')::text from pg_proc where pronamespace='public'::regnamespace and proname='handle_new_user'), 'MISSING')
union all select 25, 'C10 anon-executable SECURITY DEFINER functions outside the allowed list (expect none)', coalesce((select string_agg(proname, ', ' order by proname) from pg_proc p where p.pronamespace='public'::regnamespace and p.prosecdef and has_function_privilege('anon', p.oid, 'execute') and proname not in ('is_internal','is_client','is_admin','current_role','has_any_role','has_permission','client_company_id','can_crm','can_ops','can_finance','can_sales','can_management_read','can_orders_read','can_orders_write','can_manage_team','can_client_admin','handle_new_user','write_audit','track_order_status','prevent_lead_regression','protect_catalogue_access','write_catalogue_access_audit','payments_refresh_invoice','payments_no_overpay','quotation_requirement_guard','quotation_requirement_sync')), 'none')
union all select 26, 'C11 SECURITY DEFINER functions without a fixed search_path (expect none)', coalesce((select string_agg(proname, ', ' order by proname) from pg_proc p where p.pronamespace='public'::regnamespace and p.prosecdef and coalesce(array_to_string(proconfig, ','), '') not like '%search_path=%'), 'none')
union all select 27, 'C12 notify_users: signed-in and anon cannot run, service_role can (expect false,false,true)', coalesce(has_function_privilege('authenticated', to_regprocedure('public.notify_users(public.notification_audience, uuid, text, text, text)')::oid, 'execute')::text||','||has_function_privilege('anon', to_regprocedure('public.notify_users(public.notification_audience, uuid, text, text, text)')::oid, 'execute')::text||','||has_function_privilege('service_role', to_regprocedure('public.notify_users(public.notification_audience, uuid, text, text, text)')::oid, 'execute')::text, 'MISSING')
union all select 28, 'C13 assign_order refuses a caller with no active role (expect true,true)', coalesce((select (prosrc like '%v_role is null%')::text from pg_proc where pronamespace='public'::regnamespace and proname='assign_order'), 'MISSING')||','||coalesce(has_function_privilege('anon', to_regprocedure('public.assign_order(uuid,uuid,uuid,text)')::oid, 'execute')::text = 'false', false)::text
union all select 29, 'C14 role helpers honour is_active (expect current_role=true, has_any_role=true, is_admin=true)', coalesce((select string_agg(proname||'='||(prosrc like '%is_active%')::text, ', ' order by proname) from pg_proc where pronamespace='public'::regnamespace and proname in ('current_role','has_any_role','is_admin')), 'MISSING')
union all select 30, 'C15 record_campaign_event requires a signed-in caller (expect true)', coalesce((select (prosrc like '%auth.uid() is null%')::text from pg_proc where pronamespace='public'::regnamespace and proname='record_campaign_event'), 'MISSING')
union all select 31, 'C16 recalc_order_cost: staff costing roles only, stored profit only when ALL four cost components are entered, anon cannot run (expect true,true,true)', coalesce((select (prosrc like '%has_any_role%' and prosrc like '%''admin'', ''accounts'', ''management''%')::text from pg_proc where pronamespace='public'::regnamespace and proname='recalc_order_cost'), 'MISSING')||','||coalesce((select (prosrc like '%else 0%' and prosrc like '%greatest(coalesce(product_cost, 0), 0) > 0%' and prosrc like '%greatest(coalesce(printing_cost, 0), 0) > 0%' and prosrc like '%greatest(coalesce(courier_cost, 0), 0) > 0%' and prosrc like '%greatest(coalesce(other_cost, 0), 0) > 0%')::text from pg_proc where pronamespace='public'::regnamespace and proname='recalc_order_cost'), 'MISSING')||','||coalesce((select (not has_function_privilege('anon', oid, 'execute'))::text from pg_proc where pronamespace='public'::regnamespace and proname='recalc_order_cost'), 'MISSING')
union all select 32, 'C17 existing orders were not rewritten: 2 orders, cost totals untouched (expect 2 | 0)', (select count(*) from public.orders)::text||' | '||(select coalesce(sum(total_cost),0) from public.orders)::text
union all select 33, 'C18 products intact: total | active | HGS- | distinct SKUs | fingerprint (expect 524|524|474|524|60e683d350cd7e55a474b2b86ec87aab)', (select count(*)||'|'||count(*) filter (where status::text='active')||'|'||count(*) filter (where sku like 'HGS-%')||'|'||count(distinct sku)||'|'||md5(string_agg(id::text||'|'||coalesce(name,'')||'|'||coalesce(sku,'')||'|'||coalesce(price::text,'')||'|'||coalesce(image_url,'')||'|'||coalesce(supplier_id::text,''), ',' order by id)) from public.products)
union all select 34, 'C19 client_products rows, products with images (expect 524, 524)', (select count(*) from public.client_products)::text||', '||(select count(*) from public.products where image_url is not null and btrim(image_url) <> '')::text
