union all select 36, 'C21 old audit rows holding a non-zero cost value (expect 0; scrub is NOT needed)', (select count(*) from public.audit_logs a where a.entity in ('products','orders') and exists (select 1 from unnest(array['supplier_cost','internal_margin','product_cost','printing_cost','courier_cost','other_cost','total_cost','gross_profit']) k where coalesce(a.new_value->>k,'0') not in ('0','0.00','') or coalesce(a.previous_value->>k,'0') not in ('0','0.00','')))::text
) t order by n;

